package com.example.domain.model.i18n

internal object DuaDe3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_kufr_faqr" to DuaText("Zuflucht vor Unglauben und Armut", "O Allah, ich suche Zuflucht bei Dir vor Unglauben und Armut, und ich suche Zuflucht bei Dir vor der Strafe des Grabes. Es gibt keinen Gott außer Dir.", "Dreimal morgens und abends.", "Abu Bakrah (RA) hörte den Propheten ﷺ dies sagen."),
        "dua_alimal_ghayb" to DuaText("Kenner des Verborgenen", "O Allah, Kenner des Verborgenen und des Sichtbaren, Schöpfer der Himmel und der Erde, Herr und Herrscher aller Dinge! Ich bezeuge, dass es keinen Gott außer Dir gibt. Ich suche Zuflucht bei Dir vor dem Übel meines eigenen Selbst und vor dem Übel Satans und seinem Ruf zum Schirk.", "Morgens, abends und vor dem Schlafen — der Prophet ﷺ lehrte es Abu Bakr (RA).", "Schutz vor dem Übel des Selbst und Satans."),
        "dua_fitratil_islam" to DuaText("Auf der Fitrah des Islam", "Wir haben den Morgen auf der Fitrah des Islam erreicht, auf dem Wort der Aufrichtigkeit, auf der Religion unseres Propheten Muhammad ﷺ und auf dem Weg unseres Vaters Ibrahim (Friede sei mit ihm), der aufrecht und Muslim war und nicht zu den Götzendienern gehörte.", "Am Morgen.", "Den Glauben jeden Morgen erneuern."),
        "dua_tahleel_10_fajr" to DuaText("Zehn Tahlil nach Fajr und Maghrib", "Es gibt keinen Gott außer Allah, allein, ohne Partner. Ihm gehört die Herrschaft, Ihm gebührt das Lob; Er gibt Leben und lässt sterben, und Er hat Macht über alle Dinge.", "Zehnmal nach Fajr (und Maghrib), bevor man seinen Sitzplatz verlässt oder spricht.", "Zehn gute Taten, zehn Sünden getilgt, zehn Ränge erhöht und Schutz vor Satan den ganzen Tag."),
        "dua_amsayna_fitrah" to DuaText("Abends auf der Fitrah des Islam", "Wir haben den Abend auf der Fitrah des Islam erreicht, auf dem Wort der Aufrichtigkeit, auf der Religion unseres Propheten Muhammad ﷺ und auf dem Weg unseres Vaters Ibrahim (Friede sei mit ihm), der aufrecht und Muslim war und nicht zu den Götzendienern gehörte.", "Am Abend.", "Den Glauben jeden Abend erneuern."),
        "dua_sabr" to DuaText("Für Geduld und Standhaftigkeit", "Unser Herr, gieße Geduld über uns aus, festige unsere Füße und hilf uns gegen das ungläubige Volk.", "In Zeiten der Not und Konfrontation.", "Das Bittgebet der Armee Taluts."),
        "dua_rabbana_innana_amanna" to DuaText("Vergebung und Schutz vor dem Feuer", "Unser Herr, wir haben geglaubt, so vergib uns unsere Sünden und bewahre uns vor der Strafe des Feuers.", "Ein koranisches Bittgebet.", "Ein Bittgebet unter den Eigenschaften der Gottesfürchtigen genannt."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Rechtleitung in unserer Angelegenheit (Höhlengefährten)", "Unser Herr, gewähre uns Barmherzigkeit von Dir und bereite uns Rechtleitung in unserer Angelegenheit.", "Das Bittgebet der Höhlengefährten.", "Rechtleitung bei Entscheidungen und schwierigen Situationen."),
        "dua_musa_faqir" to DuaText("Bittgebet des Musa (Friede sei mit ihm) um Versorgung", "Mein Herr, wahrlich, ich bin bedürftig nach jedem Guten, das Du zu mir herabsendest.", "Um Versorgung und Gutes bitten — das Bittgebet des Musa (Friede sei mit ihm) in Madyan.", "Nach diesem Bittgebet gewährte Allah Musa (Friede sei mit ihm) ein Heim, Arbeit und eine Frau."),
        "dua_ayyub" to DuaText("Bittgebet des Ayyub (Friede sei mit ihm) in der Krankheit", "(Mein Herr,) mich hat Leid getroffen, und Du bist der Barmherzigste der Barmherzigen.", "In Krankheit und Leid.", "Allah nahm das Leid Ayyubs (Friede sei mit ihm) hinweg."),
        "dua_husn_khatimah" to DuaText("Als Muslim sterben (Yusuf, Friede sei mit ihm)", "Schöpfer der Himmel und der Erde, Du bist mein Beschützer in dieser Welt und im Jenseits. Lass mich als Muslim sterben und vereine mich mit den Rechtschaffenen.", "Ein Bittgebet für ein gutes Ende.", "Das Bittgebet des Propheten Yusuf (Friede sei mit ihm)."),
        "dua_shaitan_hamazat" to DuaText("Zuflucht vor den Einflüsterungen der Teufel", "Mein Herr, ich suche Zuflucht bei Dir vor den Einflüsterungen der Teufel, und ich suche Zuflucht bei Dir, mein Herr, dass sie mir nahekommen.", "Zuflucht vor satanischen Einflüsterungen.", "Ein koranisches Bittgebet um Zuflucht."),
        "dua_bad_character" to DuaText("Zuflucht vor schlechtem Charakter", "O Allah, ich suche Zuflucht bei Dir vor schlechtem Charakter, schlechten Taten und bösen Begierden.", "Zuflucht vor schlechtem Charakter, Taten und Begierden.", "Ein Zufluchtsgebet des Propheten ﷺ."),
        "dua_zawal_nimah" to DuaText("Zuflucht vor dem Verlust von Gnaden", "O Allah, ich suche Zuflucht bei Dir vor dem Verlust Deiner Gnaden, vor der Veränderung des Wohlergehens, das Du gewährt hast, vor Deiner plötzlichen Strafe und vor all Deinem Missfallen.", "Zuflucht vor dem Verlust von Gnaden und vor plötzlichem Unglück.", "Ein Bittgebet des Propheten ﷺ."),
        "dua_useless_knowledge" to DuaText("Zuflucht vor nutzlosem Wissen", "O Allah, ich suche Zuflucht bei Dir vor Wissen, das nicht nützt, vor einem Herzen, das sich nicht fürchtet, vor einer Seele, die nie satt wird, und vor einem Bittgebet, das nicht erhört wird.", "Zuflucht vor nutzlosem Wissen und einem Herzen ohne Gottesfurcht.", "Ein Zufluchtsgebet des Propheten ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Nützliches Wissen und erlaubte Versorgung", "O Allah, ich bitte Dich um nützliches Wissen, reine Versorgung und angenommene Taten.", "Nach dem Fajr-Gebet.", "Der Prophet ﷺ sprach dies nach dem Salam des Fajr-Gebets."),
        "dua_leprosy_diseases" to DuaText("Zuflucht vor schweren Krankheiten", "O Allah, ich suche Zuflucht bei Dir vor Vitiligo, Wahnsinn, Lepra und allen üblen Krankheiten.", "Schutz vor schweren Krankheiten.", "Ein Sunna-Bittgebet zum Erhalt der Gesundheit."),
        "dua_fear_people" to DuaText("Furcht vor Feinden oder Unterdrückern", "O Allah, wir stellen Dich vor sie und suchen Zuflucht bei Dir vor ihrem Übel.", "Bei Furcht vor dem Schaden eines Volkes oder einer Person.", "Der Prophet ﷺ sprach dies, als er ein Volk fürchtete."),
        "dua_shirk_protection" to DuaText("Schutz vor verborgenem Schirk", "O Allah, ich suche Zuflucht bei Dir davor, wissentlich etwas neben Dich zu stellen, und ich bitte Dich um Vergebung für das, was ich unwissentlich tue.", "Um vor Zurschaustellung und verborgenem Schirk sicher zu sein.", "Verborgener Schirk ist verborgener als das Kriechen einer Ameise."),
        "dua_rain" to DuaText("Wenn es regnet", "O Allah, (sende) einen nützlichen Regen.", "Wenn es regnet.", "Der Regen ist eine Zeit, in der Bittgebete erhört werden."),
        "dua_after_rain" to DuaText("Nach dem Regen", "Uns wurde Regen gegeben durch die Gnade Allahs und Seine Barmherzigkeit.", "Nach dem Regen.", "Wer dies sagt, ist ein Gläubiger an Allah."),
        "dua_istisqa" to DuaText("Um Regen bitten (Istisqa)", "O Allah, sende uns Regen (dreimal).", "Wenn es keinen Regen gibt.", "Der Prophet ﷺ sprach dieses Bittgebet in der Freitagspredigt, und es regnete."),
        "dua_heavy_rain" to DuaText("Übermäßiger Regen", "O Allah, (lass ihn fallen) um uns herum und nicht auf uns.", "Bei zu viel Regen.", "Die Wolken zogen sich durch das Bittgebet des Propheten ﷺ zurück."),
        "dua_wind" to DuaText("Wenn der Wind weht", "O Allah, ich bitte Dich um sein Gutes, das Gute darin und das Gute dessen, womit er gesandt wurde, und ich suche Zuflucht bei Dir vor seinem Übel, dem Übel darin und dem Übel dessen, womit er gesandt wurde.", "Bei starkem Wind oder Sturm.", "Der Prophet ﷺ sprach dieses Bittgebet während Stürmen."),
        "dua_thunder" to DuaText("Beim Hören von Donner", "Gepriesen sei Der, den der Donner mit Seinem Lob preist, und die Engel aus Furcht vor Ihm.", "Beim Hören von Donner — die Praxis von Abdullah ibn az-Zubayr (RA).", "Entnommen aus Surah ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Den Neumond sehen", "O Allah, lass diesen Mond mit Segen, Glauben, Sicherheit und Islam über uns aufgehen. (O Mond,) mein Herr und dein Herr ist Allah.", "Beim Sehen des Neumonds.", "Das Sunna-Bittgebet für jeden neuen Monat."),
        "dua_janaza_adult" to DuaText("Totengebet (Erwachsener)", "O Allah, vergib unseren Lebenden und unseren Toten, den Anwesenden und den Abwesenden, unseren Jungen und unseren Alten, unseren Männern und unseren Frauen. O Allah, wen von uns Du am Leben lässt, den lass im Islam leben, und wen von uns Du sterben lässt, den lass im Glauben sterben.", "Nach dem dritten Takbir des Totengebets.", "Das Sunna-Bittgebet für einen verstorbenen Erwachsenen."),
        "dua_janaza_child" to DuaText("Totengebet (Kind)", "O Allah, mache ihn zu einem Vorläufer (und Gastgeber) für uns, mache ihn zu einem Lohn und Schatz für uns, und mache ihn zu einem Fürsprecher für uns, dessen Fürsprache angenommen wird.", "Im Totengebet für ein Kind (für ein Mädchen sagt man 'ij'alhā').", "Das Sunna-Bittgebet, praktiziert von den Hanafiten."),
        "dua_mayyit_awf" to DuaText("Ausführliches Bittgebet für den Verstorbenen", "O Allah, vergib ihm, erbarme Dich seiner, gib ihm Wohlergehen und verzeih ihm. Mache seinen Empfang ehrenvoll und sein Grab geräumig, wasche ihn mit Wasser, Schnee und Hagel, und reinige ihn von Sünden, wie ein weißes Gewand von Schmutz gereinigt wird.", "Im Totengebet oder für den Verstorbenen.", "Awf ibn Malik (RA) wünschte, er wäre dieser Verstorbene gewesen."),
        "dua_visiting_graves" to DuaText("Gräber besuchen", "Friede sei mit euch, o gläubige und muslimische Bewohner dieser Wohnstätten. Auch wir, so Allah will, werden uns euch anschließen. Ich bitte Allah um Wohlergehen für uns und für euch.", "Beim Betreten des Friedhofs.", "Gräberbesuche erinnern an den Tod und das Jenseits."),
        "dua_closing_eyes" to DuaText("Beim Schließen der Augen des Verstorbenen", "O Allah, vergib (Name), erhöhe seinen Rang unter den Rechtgeleiteten, sei sein Nachfolger unter denen, die er zurücklässt. Vergib uns und ihm, o Herr der Welten; mache sein Grab geräumig und fülle es mit Licht.", "Beim Schließen der Augen des Verstorbenen (unter Nennung seines Namens).", "Der Prophet ﷺ sprach dieses Bittgebet für Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Beileid (Ta'ziyah)", "Wahrlich, Allah gehört, was Er nahm, und Ihm gehört, was Er gab, und alles bei Ihm hat eine festgesetzte Frist, also sei geduldig und hoffe auf Lohn.", "Beileid einer Familie nach einem Todesfall aussprechen.", "Der Prophet ﷺ sandte diese Botschaft an seine Tochter."),
        "dua_placing_in_grave" to DuaText("Den Verstorbenen ins Grab legen", "Im Namen Allahs und auf dem Weg des Gesandten Allahs ﷺ.", "Beim Hinablegen des Verstorbenen ins Grab.", "Das Sunna-Bittgebet der Bestattung."),
        "dua_sneezing" to DuaText("Niesen", "Alles Lob gebührt Allah. — Möge Allah sich deiner erbarmen. — Möge Allah dich rechtleiten und deine Angelegenheiten in Ordnung bringen.", "Beim Niesen; der Zuhörer sagt 'Yarhamukallah', dann antwortet der Niesende.", "Es ist eines der Rechte eines Muslims gegenüber einem anderen Muslim."),
        "dua_toilet_enter" to DuaText("Die Toilette betreten", "Im Namen Allahs. O Allah, ich suche Zuflucht bei Dir vor den männlichen und weiblichen unreinen Dschinn.", "Vor dem Betreten der Toilette mit dem linken Fuß.", "Bismillah wird zu einem Schutzschild zwischen den Dschinn und der Person."),
        "dua_toilet_exit" to DuaText("Die Toilette verlassen", "(O Allah,) ich bitte Dich um Vergebung.", "Beim Verlassen der Toilette mit dem rechten Fuß.", "Der Prophet ﷺ sagte dies beim Verlassen der Toilette."),
        "dua_thanking" to DuaText("Jemandem danken", "Möge Allah dich mit Gutem belohnen.", "Wenn dir jemand einen Gefallen tut.", "Wer dies sagt, hat seinen Dank vollständig zum Ausdruck gebracht."),
        "dua_love_for_allah" to DuaText("Wenn jemand sagt 'Ich liebe dich um Allahs willen'", "Möge Er (Allah), um dessentwillen du mich liebst, dich lieben.", "Wenn jemand sagt 'Ich liebe dich um Allahs willen'.", "Die Sunna-Antwort auf Liebe um Allahs willen."),
        "dua_seeing_muslim_smile" to DuaText("Gruß (Salam)", "Friede sei mit euch, und die Barmherzigkeit Allahs und Seine Segnungen.", "Beim Treffen eines Muslims.", "Der vollständige Salam bringt dreißig gute Taten ein."),
        "dua_dressing" to DuaText("Sich ankleiden", "Alles Lob gebührt Allah, der mich damit bekleidet und es mir ohne meine Kraft oder Macht gewährt hat.", "Beim Ankleiden.", "Frohe Botschaft der Vergebung vergangener Sünden."),
        "dua_rooster_donkey" to DuaText("Einen Hahn oder Esel hören", "O Allah, ich bitte Dich um Deine Großzügigkeit (Hahn). — Ich suche Zuflucht bei Allah vor Satan, dem Verfluchten (Esel).", "Beim Hören eines Hahns um Allahs Großzügigkeit bitten; beim Hören eines Esels Zuflucht vor Satan suchen.", "Der Hahn sieht einen Engel und der Esel sieht einen Teufel."),
        "dua_something_liked" to DuaText("Etwas Bewundernswertes sehen (gegen den bösen Blick)", "Was Allah gewollt hat. O Allah, segne es.", "Beim Sehen von etwas Bewundernswertem, das jemandem gehört, um Segen bitten.", "Um Segen zu bitten verhindert den bösen Blick."),
        "dua_sell_buy_debt_repaid" to DuaText("Beim Begleichen einer Schuld", "Möge Allah dich in deiner Familie und deinem Vermögen segnen.", "Für den Gläubiger bei der Rückzahlung einer Schuld.", "Der Lohn für ein Darlehen ist Dank und Rückzahlung."),
        "dua_talbiyah" to DuaText("Talbiyah", "Hier bin ich, o Allah, hier bin ich. Hier bin ich, Du hast keinen Partner, hier bin ich. Wahrlich, alles Lob, alle Gnade und Herrschaft gehören Dir. Du hast keinen Partner.", "Laut nach dem Anlegen des Ihram.", "Das Erkennungszeichen von Hajj und Umrah."),
        "dua_yamani_hajar" to DuaText("Zwischen Rukn Yamani und dem Schwarzen Stein", "Unser Herr, gib uns Gutes in dieser Welt und Gutes im Jenseits, und bewahre uns vor der Strafe des Feuers.", "Beim Tawaf, zwischen der jemenitischen Ecke und dem Schwarzen Stein.", "Der Prophet ﷺ rezitierte dies an dieser Stelle im Tawaf."),
        "dua_safa_marwa" to DuaText("Auf Safa und Marwah", "Es gibt keinen Gott außer Allah, allein, ohne Partner. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge. Es gibt keinen Gott außer Allah allein; Er erfüllte Sein Versprechen, half Seinem Diener und besiegte allein die Verbündeten.", "Beim Besteigen von Safa mit Blick zur Qibla (dreimal).", "Das Dhikr des Propheten ﷺ auf Safa und Marwah."),
        "dua_arafah" to DuaText("Bestes Bittgebet des Tages von Arafah", "Es gibt keinen Gott außer Allah, allein, ohne Partner. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge.", "Der Tag von Arafah — das beste Bittgebet.", "Das beste Bittgebet ist das Bittgebet des Tages von Arafah, und die besten Worte sind diese."),
        "dua_takbeer_tashreeq" to DuaText("Takbir-e-Tashreeq", "Allah ist der Größte, Allah ist der Größte. Es gibt keinen Gott außer Allah. Allah ist der Größte, Allah ist der Größte, und alles Lob gebührt Allah.", "Nach jedem Pflichtgebet von Fajr des 9. Dhul-Hijjah bis Asr des 13. Dhul-Hijjah.", "Überliefert von Ali und Ibn Mas'ud (RA) — nach den Hanafiten wajib."),
        "dua_zamzam" to DuaText("Zamzam trinken", "O Allah, ich bitte Dich um nützliches Wissen, reichliche Versorgung und Heilung von jeder Krankheit.", "Beim Trinken von Zamzam, bitte um das, was du beabsichtigst.", "Zamzam ist für das, wofür es getrunken wird (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Über die Schöpfung nachdenken", "Unser Herr, Du hast all dies nicht umsonst erschaffen. Gepriesen seist Du, bewahre uns also vor der Strafe des Feuers.", "Das Bittgebet derer, die über die Schöpfung der Himmel und der Erde nachdenken.", "Das Bittgebet der Verständigen (Ulul-Albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Wir hörten den Rufer zum Glauben", "Unser Herr, wir hörten einen Rufer, der zum Glauben rief und sagte 'Glaubt an euren Herrn', und wir glaubten. Unser Herr, vergib uns unsere Sünden, tilge unsere Missetaten und lass uns mit den Rechtschaffenen sterben.", "Ein Bittgebet für Glauben und ein gutes Ende.", "Ein Bittgebet um Vergebung und ein gutes Ende."),
        "dua_q_atina_ma_waadtana" to DuaText("Gib uns, was Du versprochen hast", "Unser Herr, gewähre uns, was Du uns durch Deine Gesandten versprochen hast, und beschäme uns nicht am Tag der Auferstehung. Wahrlich, Du brichst Dein Versprechen nicht.", "Zuflucht vor Schande am Tag der Auferstehung.", "Ehre im Jenseits suchen."),
        "dua_q_israfana" to DuaText("Vergib unsere Maßlosigkeit", "Unser Herr, vergib uns unsere Sünden und unsere Maßlosigkeit in unseren Angelegenheiten, festige unsere Füße und hilf uns gegen das ungläubige Volk.", "Das Bittgebet der Gefährten früherer Propheten.", "Ein Bittgebet für Standhaftigkeit und Vergebung."),
        "dua_q_jamiun_nas" to DuaText("Du wirst die Menschheit versammeln", "Unser Herr, Du wirst gewiss die Menschheit an einem Tag versammeln, an dem kein Zweifel besteht. Wahrlich, Allah bricht Sein Versprechen nicht.", "Gewissheit über den Tag der Auferstehung bekräftigen.", "Das Bittgebet derer, die fest im Wissen verwurzelt sind."),
        "dua_q_maash_shahidin" to DuaText("Schreibe uns unter die Zeugen", "Unser Herr, wir haben geglaubt, also schreibe uns unter die Zeugen.", "Das Bittgebet derer, die die Wahrheit erkannten und glaubten.", "Ein Bittgebet für die Annahme des eigenen Glaubens."),
        "dua_q_la_tajalna_zalimin" to DuaText("Nicht mit den Ungerechten", "Unser Herr, stelle uns nicht mit dem ungerechten Volk.", "Das Bittgebet der Leute von al-A'raf.", "Zuflucht vor dem Schicksal der Ungerechten."),
        "dua_q_tawaffana_muslimin" to DuaText("Geduld und Tod als Muslime", "Unser Herr, gieße Geduld über uns aus und lass uns als Muslime sterben.", "Das Bittgebet der Zauberer des Pharao, als sie glaubten.", "Geduld in der Prüfung und ein Ende im Glauben."),
        "dua_q_la_tajalna_fitnah" to DuaText("Keine Prüfung für die Unterdrücker", "Auf Allah verlassen wir uns. Unser Herr, mache uns nicht zu einer Prüfung für das ungerechte Volk, und rette uns durch Deine Barmherzigkeit vor dem ungläubigen Volk.", "Das Bittgebet des Volkes von Musa (Friede sei mit ihm).", "Ein Bittgebet um Rettung vor Unterdrückung und Unterdrückern."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Bittgebet des Nuh (Friede sei mit ihm) um Vergebung", "Mein Herr, ich suche Zuflucht bei Dir davor, Dich um etwas zu bitten, wovon ich kein Wissen habe. Und wenn Du mir nicht vergibst und Dich meiner nicht erbarmst, werde ich zu den Verlierern gehören.", "Das Reuegebet des Propheten Nuh (Friede sei mit ihm).", "Eine Lehre im richtigen Bitten."),
        "dua_q_mudkhala_sidq" to DuaText("Eintritt und Austritt der Wahrheit", "Mein Herr, lass mich mit Wahrheit eintreten und mit Wahrheit austreten, und gewähre mir von Dir eine unterstützende Autorität.", "Vor dem Betreten einer neuen Aufgabe, eines Hauses oder Ortes.", "Das Bittgebet, das dem Propheten ﷺ zur Zeit der Hijra gelehrt wurde."),
        "dua_q_la_tadharni_fardan" to DuaText("Bittgebet des Zakariya (Friede sei mit ihm) — Lass mich nicht allein", "Mein Herr, lass mich nicht allein, und Du bist der beste der Erben.", "Für diejenigen, die sich Kinder wünschen.", "Durch dieses Bittgebet gewährte Allah Yahya (Friede sei mit ihm)."),
        "dua_q_munzalan_mubarakan" to DuaText("Ein gesegneter Landeplatz", "Mein Herr, lass mich an einem gesegneten Ort landen, und Du bist der Beste derer, die zum Landen bringen.", "Beim Umzug in ein neues Heim oder bei einem Halt — das Bittgebet des Nuh (Friede sei mit ihm).", "Ein Bittgebet für Segen an einem neuen Ort."),
        "dua_q_amanna_faghfir" to DuaText("Wir glauben, so vergib uns", "Unser Herr, wir haben geglaubt, so vergib uns und erbarme Dich unser, und Du bist der Beste der Barmherzigen.", "Das Bittgebet der rechtschaffenen Diener Allahs.", "Ein umfassendes Bittgebet um Vergebung und Barmherzigkeit."),
        "dua_q_isrif_jahannam" to DuaText("Wende die Strafe der Hölle ab", "Unser Herr, wende von uns die Strafe der Hölle ab; wahrlich, ihre Strafe ist beständig anhaftend. Wahrlich, sie ist eine üble Bleibe und Wohnstätte.", "Das Bittgebet der Diener des Allbarmherzigen ('Ibad ar-Rahman).", "Ein koranisches Bittgebet um Zuflucht vor der Hölle."),
        "dua_q_hab_li_hukman" to DuaText("Bittgebet des Ibrahim (Friede sei mit ihm) — Weisheit und das Paradies", "Mein Herr, gewähre mir Weisheit und vereine mich mit den Rechtschaffenen, gewähre mir ein ehrenvolles Andenken unter späteren Generationen, und mache mich zu einem der Erben des Gartens der Wonne.", "Um Weisheit, die Gesellschaft der Rechtschaffenen und das Paradies bitten.", "Ein umfassendes Bittgebet des Ibrahim (Friede sei mit ihm)."),
        "dua_q_lut_najjini_ahli" to DuaText("Bittgebet des Lut (Friede sei mit ihm) — Rette meine Familie", "Mein Herr, rette mich und meine Familie vor (den Folgen) dessen, was sie tun.", "Die eigene Familie vor einem Umfeld des Bösen schützen.", "Schutz der Familie vor dem Bösen."),
        "dua_q_sulaiman_awzini" to DuaText("Bittgebet des Sulaiman (Friede sei mit ihm) um Dankbarkeit", "Mein Herr, befähige mich, dankbar zu sein für Deine Gunst, die Du mir und meinen Eltern erwiesen hast, und rechtschaffene Taten zu vollbringen, die Dir gefallen, und nimm mich durch Deine Barmherzigkeit unter Deine rechtschaffenen Diener auf.", "Um die Fähigkeit bitten, für Gnaden dankbar zu sein.", "Das Dankgebet des Sulaiman (Friede sei mit ihm)."),
        "dua_q_musa_zalamtu" to DuaText("Bittgebet des Musa (Friede sei mit ihm) — Ich habe mir selbst Unrecht getan", "Mein Herr, ich habe mir selbst Unrecht getan, so vergib mir.", "Sofortige Reue nach einem Fehler.", "Allah vergab Musa (Friede sei mit ihm)."),
        "dua_q_musa_najjini" to DuaText("Bittgebet des Musa (Friede sei mit ihm) — Rette mich vor Unterdrückern", "Mein Herr, rette mich vor dem ungerechten Volk.", "Bei Furcht vor Unterdrückern.", "Das Bittgebet des Musa (Friede sei mit ihm) beim Verlassen Ägyptens."),
        "dua_q_lut_unsurni" to DuaText("Bittgebet des Lut (Friede sei mit ihm) — Hilf mir gegen die Verderber", "Mein Herr, hilf mir gegen das verderbende Volk.", "Um Hilfe gegen diejenigen, die Verderben verbreiten.", "Das Bittgebet derer, die fest auf der Wahrheit stehen."),
        "dua_q_hab_li_salihin" to DuaText("Bittgebet des Ibrahim (Friede sei mit ihm) um ein rechtschaffenes Kind", "Mein Herr, gewähre mir (ein Kind) unter den Rechtschaffenen.", "Um rechtschaffene Kinder bitten.", "Durch dieses Bittgebet wurde Isma'il (Friede sei mit ihm) gewährt."),
        "dua_q_wasita_kulla_shay" to DuaText("Bittgebet der Engel, die den Thron tragen", "Unser Herr, Du umfasst alle Dinge mit Barmherzigkeit und Wissen, so vergib denen, die bereuen und Deinem Weg folgen, und bewahre sie vor der Strafe der Hölle.", "Die Engel, die den Thron tragen, sprechen dieses Bittgebet für die Gläubigen.", "Rezitiert mit der Absicht, in das Bittgebet der Engel eingeschlossen zu sein."),
        "dua_q_ikhwanina" to DuaText("Für unsere Brüder, die uns vorausgingen", "Unser Herr, vergib uns und unseren Brüdern, die uns im Glauben vorausgingen, und lege keinen Groll in unsere Herzen gegen die Gläubigen. Unser Herr, Du bist wahrlich Gütig und Barmherzig.", "Ein Bittgebet für die vorausgegangenen Gläubigen und ein reines Herz.", "Ein Bittgebet für die edlen Gefährten (RA) und die früheren Gläubigen."),
        "dua_q_alayka_tawakkalna" to DuaText("Auf Dich vertrauen wir (Ibrahim, Friede sei mit ihm)", "Unser Herr, auf Dich vertrauen wir, zu Dir wenden wir uns und zu Dir ist die Rückkehr. Unser Herr, mache uns nicht zu einer Prüfung für die Ungläubigen und vergib uns. Unser Herr, Du bist wahrlich der Allmächtige, der Allweise.", "Das Bittgebet des Ibrahim (Friede sei mit ihm) und seiner Gefährten.", "Ein Bittgebet des Vertrauens auf Allah und der Hinwendung zu Ihm."),
        "dua_q_atmim_nurana" to DuaText("Vollende unser Licht", "Unser Herr, vollende für uns unser Licht und vergib uns. Wahrlich, Du hast Macht über alle Dinge.", "Das Bittgebet der Gläubigen am Tag der Auferstehung.", "Um Licht auf dem Sirat bitten."),
        "dua_q_asiya_baytan" to DuaText("Bittgebet der Asiya — Ein Haus im Paradies", "Mein Herr, baue mir bei Dir ein Haus im Paradies, rette mich vor Pharao und seinen Taten, und rette mich vor dem ungerechten Volk.", "Das Bittgebet der Asiya, der Frau des Pharao.", "Allah machte sie zu einem Beispiel für die Gläubigen."),
        "dua_adhan_response" to DuaText("Auf den Adhan antworten", "Es gibt keine Kraft und keine Macht außer durch Allah.", "Wiederhole, was der Muezzin sagt; bei 'Hayya 'alas-salah' und 'Hayya 'alal-falah' sage dies.", "Wer von Herzen antwortet, wird ins Paradies eintreten."),
        "dua_adhan_shahadah" to DuaText("Nach der Shahada des Muezzins", "Und auch ich bezeuge, dass es keinen Gott außer Allah gibt, allein, ohne Partner, und dass Muhammad ﷺ Sein Diener und Gesandter ist. Ich bin zufrieden mit Allah als Herr, mit Muhammad ﷺ als Gesandtem und mit dem Islam als Religion.", "Beim Hören des Glaubensbekenntnisses des Muezzins.", "Seine Sünden werden vergeben."),
        "dua_istiftah_baid" to DuaText("Eröffnungsgebet: Entferne mich von Sünden", "O Allah, entferne mich von meinen Sünden, wie Du den Osten vom Westen entfernt hast. O Allah, reinige mich von Sünden, wie ein weißes Gewand von Schmutz gereinigt wird. O Allah, wasche meine Sünden mit Wasser, Schnee und Hagel ab.", "Nach dem Eröffnungstakbir (kann auch anstelle der Sana gesprochen werden).", "Der Prophet ﷺ rezitierte dies zwischen dem Takbir und der Rezitation."),
        "dua_hamdan_kathiran" to DuaText("Reichliches Lob nach dem Ruku", "Unser Herr, Dir gebührt Lob — reichliches, reines und gesegnetes Lob.", "Nach dem Aufrichten aus dem Ruku, zusammen mit 'Rabbana lakal-hamd'.", "Über dreißig Engel wetteiferten darum, es zuerst aufzuschreiben."),
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku und Sujud)", "(Allah ist) hochgepriesen, allerheiligst, Herr der Engel und des Geistes (Jibril).", "Im Ruku und Sujud.", "Der Prophet ﷺ rezitierte dies im Ruku und Sujud."),
        "dua_sujood_dhanbi_kullah" to DuaText("Im Sujud: Vergib alle meine Sünden", "O Allah, vergib mir alle meine Sünden — die kleinen und die großen, die ersten und die letzten, die offenen und die verborgenen.", "Im Sujud.", "Die Prostration ist ein Ort, an dem Bittgebete erhört werden."),
        "dua_sujood_ridaka" to DuaText("Zuflucht in Deinem Wohlgefallen", "O Allah, ich suche Zuflucht in Deinem Wohlgefallen vor Deinem Zorn, in Deiner Vergebung vor Deiner Strafe, und ich suche Zuflucht bei Dir vor Dir. Ich kann Dich nicht vollständig loben; Du bist so, wie Du Dich selbst gelobt hast.", "Im Sujud — Aisha (RA) hörte den Propheten ﷺ dies sagen.", "Ein Sujud-Bittgebet des Propheten ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Alle verbalen, körperlichen und finanziellen Akte der Anbetung gehören Allah. Friede sei mit dir, o Prophet, und die Barmherzigkeit Allahs und Seine Segnungen. Friede sei mit uns und mit den rechtschaffenen Dienern Allahs. Ich bezeuge, dass es keinen Gott außer Allah gibt, und ich bezeuge, dass Muhammad ﷺ Sein Diener und Gesandter ist.", "In jeder Sitzung — überliefert von Abdullah ibn Mas'ud (RA) (die hanafitische Praxis).", "Der Prophet ﷺ lehrte es wie eine Sure des Korans."),
        "dua_sajdah_tilawah" to DuaText("Sadschda der Rezitation", "Mein Gesicht hat sich vor Dem niedergeworfen, Der es erschaffen und sein Hören und Sehen durch Seine Macht und Kraft hervorgebracht hat.", "In der Prostration der Rezitation.", "Der Prophet ﷺ sagte dies in der Prostration der Rezitation bei Nacht."),
        "dua_after_witr" to DuaText("Nach dem Witr", "Gepriesen sei der König, der Allerheiligste.", "Dreimal nach dem Salam des Witr, wobei die Stimme beim dritten Mal erhoben wird.", "Der Prophet ﷺ sagte dies nach dem Witr."),
        "dua_tahajjud_nur" to DuaText("Eröffnungsbittgebet des Tahajjud", "O Allah, Dir gebührt Lob; Du bist der Erhalter der Himmel, der Erde und all dessen, was in ihnen ist. Dir gebührt Lob; Du bist das Licht der Himmel, der Erde und all dessen, was in ihnen ist. Dir gebührt Lob; Du bist die Wahrheit, Dein Versprechen ist wahr, die Begegnung mit Dir ist wahr, Dein Wort ist wahr, das Paradies ist wahr, die Hölle ist wahr, die Propheten sind wahr, Muhammad ﷺ ist wahr und die Stunde ist wahr.", "Zu Beginn des Nachtgebets (Tahajjud) (der einleitende Teil des Bittgebets).", "Der Prophet ﷺ rezitierte dies beim Aufstehen zum Tahajjud (das vollständige Bittgebet steht in al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Leite mich in strittigen Angelegenheiten", "O Allah, Herr von Jibril, Mika'il und Israfil, Schöpfer der Himmel und der Erde, Kenner des Verborgenen und des Sichtbaren! Du wirst zwischen Deinen Dienern über das richten, worüber sie uneins waren. Leite mich mit Deiner Erlaubnis zur Wahrheit in dem, worüber Uneinigkeit besteht. Wahrlich, Du leitest, wen Du willst, auf einen geraden Weg.", "Zu Beginn des Tahajjud — um Rechtleitung zur Wahrheit inmitten von Uneinigkeit.", "Der Prophet ﷺ begann sein Nachtgebet mit diesem Bittgebet."),
        "dua_going_to_mosque_nur" to DuaText("Zur Moschee gehen (Lichtgebet)", "O Allah, gib Licht in mein Herz, Licht in meine Augen, Licht in meine Ohren, Licht zu meiner Rechten, Licht zu meiner Linken, Licht über mir, Licht unter mir, Licht vor mir, Licht hinter mir, und mach mir Licht.", "Auf dem Weg zur Moschee für Fajr.", "Der Prophet ﷺ rezitierte dies auf dem Weg zum Gebet."),
        "dua_waswasa_salah" to DuaText("Waswasa während des Gebets (Khinzab)", "Ich suche Zuflucht bei Allah vor Satan, dem Verfluchten.", "Wenn satanische Einflüsterungen während des Gebets kommen, Zuflucht suchen und dreimal leicht trocken nach links ausspucken.", "Uthman ibn Abil-'As (RA) tat dies, und die Einflüsterungen verschwanden."),
        "dua_la_hawla_kanz" to DuaText("Ein Schatz des Paradieses", "Es gibt keine Kraft und keine Macht außer durch Allah.", "Häufig, zu allen Zeiten.", "Es ist einer der Schätze des Paradieses."),
        "dua_four_beloved_words" to DuaText("Die vier geliebtesten Worte", "Gepriesen sei Allah, alles Lob gebührt Allah, es gibt keinen Gott außer Allah, und Allah ist der Größte.", "Die Worte, die Allah am liebsten sind.", "Sie sind dem Propheten ﷺ lieber als alles, worüber die Sonne aufgeht."),
        "dua_two_light_words" to DuaText("Zwei Worte, leicht auf der Zunge", "Gepriesen sei Allah und alles Lob gehört Ihm; gepriesen sei Allah, der Erhabene.", "Leicht auf der Zunge, schwer auf der Waage.", "Geliebt vom Allbarmherzigen, leicht auf der Zunge und schwer auf der Waage. (Der letzte Hadith von al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "O Besitzer von Majestät und Ehre!", "Halte daran fest im Bittgebet — die Anweisung des Propheten ﷺ.", "Der Prophet ﷺ sagte: Halte fest an 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_sleep_wadatu_janbi" to DuaText("In Deinem Namen lege ich mich nieder", "In Deinem Namen, mein Herr, lege ich meine Seite nieder, und in Deinem Namen erhebe ich mich. Wenn Du meine Seele nimmst, erbarme Dich ihrer, und wenn Du sie freilässt, beschütze sie, wie Du Deine rechtschaffenen Diener beschützt.", "Nach dem Abstauben des Bettes und dem Hinlegen.", "Die eigene Seele Allah anvertrauen vor dem Schlafen."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Du hast meine Seele erschaffen", "O Allah, Du hast meine Seele erschaffen und Du wirst sie nehmen. Ihr Tod und ihr Leben gehören Dir. Wenn Du sie am Leben lässt, beschütze sie, und wenn Du sie sterben lässt, vergib ihr. O Allah, ich bitte Dich um Wohlergehen.", "Vor dem Schlafen — überliefert von Ibn Umar (RA).", "Der Prophet ﷺ wies an, dies vor dem Schlafengehen zu sagen."),
        "dua_sleep_atamana" to DuaText("Dankbarkeit vor dem Schlafen", "Alles Lob gebührt Allah, der uns ernährt, uns zu trinken gegeben, uns versorgt und uns Unterkunft gewährt hat. Wie viele gibt es, die niemanden haben, der sie versorgt oder ihnen Unterkunft gewährt.", "Beim Zubettgehen.", "Der Prophet ﷺ sagte dies beim Zubettgehen."),
        "dua_sleep_rabbas_samawat" to DuaText("Herr der Himmel — Begleiche unsere Schuld", "O Allah, Herr der Himmel, der Erde und des mächtigen Throns, unser Herr und Herr aller Dinge, Spalter des Samens und des Dattelkerns, Offenbarer der Thora, des Injil und des Furqan! Ich suche Zuflucht bei Dir vor dem Übel von allem, dessen Stirnlocke Du hältst. O Allah, Du bist der Erste, es gibt nichts vor Dir; Du bist der Letzte, es gibt nichts nach Dir; Du bist der Offenbare, es gibt nichts über Dir; Du bist der Verborgene, nichts ist Dir verborgen. Begleiche unsere Schuld für uns und befreie uns von Armut.", "Vor dem Schlafen, auf der rechten Seite liegend — Fatimah (RA) gelehrt.", "Ein Bittgebet um Erleichterung von Schulden und Not."),
        "dua_sleep_fear" to DuaText("Angst oder Unruhe im Schlaf", "Ich suche Zuflucht in den vollkommenen Worten Allahs vor Seinem Zorn und Seiner Strafe, vor dem Übel Seiner Diener, und vor den Einflüsterungen der Teufel und ihrem Kommen zu mir.", "Bei Angst oder Unruhe im Schlaf.", "Wer dies tut, dem wird jene Sache nicht schaden."),
        "dua_waking_afani" to DuaText("Erwachen: Er stellte meine Seele wieder her", "Alles Lob gebührt Allah, der meinem Körper Wohlergehen gab, mir meine Seele zurückgab und mir erlaubte, Seiner zu gedenken.", "Beim Erwachen.", "Dankbarkeit für einen neuen Morgen."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah ist mein Herr", "Allah, Allah ist mein Herr; ich stelle Ihm nichts zur Seite.", "In Kummer oder Not — der Prophet ﷺ lehrte es Asma bint Umays (RA).", "Am Tauhid festhalten in Zeiten der Not."),
        "dua_rahmataka_arju" to DuaText("Deine Barmherzigkeit erhoffe ich", "O Allah, es ist Deine Barmherzigkeit, auf die ich hoffe, so überlasse mich nicht mir selbst, auch nicht für einen Augenblick, und ordne alle meine Angelegenheiten. Es gibt keinen Gott außer Dir.", "Das Bittgebet des Bedrängten (Da'awat al-makrub).", "Der Prophet ﷺ nannte es das Bittgebet des Bedrängten."),
        "dua_against_enemy_ahzab" to DuaText("Gegen die Heere des Feindes", "O Allah, Offenbarer des Buches, Schnell im Rechnen! Besiege die Verbündeten. O Allah, besiege sie und erschüttere sie.", "Gegen den Feind — das Bittgebet der Schlacht der Verbündeten.", "Das Bittgebet des Propheten ﷺ gegen den Feind."),
        "dua_anta_adudi" to DuaText("Du bist meine Stütze", "O Allah, Du bist meine Stütze und mein Helfer. Durch Dich plane ich, durch Dich schreite ich voran und durch Dich kämpfe ich.", "Vor einem Wettstreit oder einer großen Herausforderung.", "Der Prophet ﷺ sagte dies in der Schlacht."),
        "dua_ikfinihim" to DuaText("Reiche mir gegen sie", "O Allah, sei mir genug gegen sie, wie Du willst.", "Gegen das Übel von Unterdrückern — das Bittgebet des Jungen in der Geschichte der Leute des Grabens.", "Allah rettete den Jungen vor den Unterdrückern."),
        "dua_qadarullah" to DuaText("Wenn etwas Schlimmes passiert", "Es ist die Bestimmung Allahs, und Er tat, was Er wollte.", "Wenn etwas Unangenehmes geschieht, anstatt 'wenn nur' zu sagen.", "'Wenn nur' öffnet die Tür für Satan."),
        "dua_ala_kulli_hal" to DuaText("Lob in jeder Situation", "Alles Lob gebührt Allah in jeder Situation.", "Wenn etwas Unerwünschtes geschieht.", "Der Prophet ﷺ sagte dies angesichts von etwas, das ihm missfiel."),
        "dua_dogs_barking" to DuaText("Hunde bellen in der Nacht hören", "Ich suche Zuflucht bei Allah vor Satan, dem Verfluchten.", "Beim Hören von bellenden Hunden oder eines schreienden Esels in der Nacht.", "Sie sehen, was du nicht siehst."),
        "dua_leaving_home_adilla" to DuaText("Zuflucht vor dem Irregehen", "O Allah, ich suche Zuflucht bei Dir davor, in die Irre zu gehen oder irregeleitet zu werden, davor, auszurutschen oder zum Ausrutschen gebracht zu werden, davor, Unrecht zu tun oder Unrecht erlitten zu werden, davor, töricht zu handeln oder töricht behandelt zu werden.", "Beim Verlassen des Hauses — überliefert von Umm Salamah (RA).", "Der Prophet ﷺ rezitierte dies jedes Mal, wenn er sein Haus verließ."),
        "dua_ascending_descending" to DuaText("Bergauf und bergab gehen", "Allah ist der Größte (bergauf). — Gepriesen sei Allah (bergab).", "Auf einer Reise, sage 'Allahu Akbar' beim Aufstieg und 'SubhanAllah' beim Abstieg.", "Die Praxis der Gefährten (RA) auf Reisen."),
        "dua_traveller_sahar" to DuaText("Reisegebet vor der Morgendämmerung", "Ein Zuhörer hat unser Lob Allahs und Seine guten Gaben an uns gehört (und weitergegeben). Unser Herr, begleite uns und gewähre uns Deine Gunst — (dies sage ich) indem ich Zuflucht bei Allah vor dem Feuer suche.", "Auf einer Reise, vor der Morgendämmerung.", "Der Prophet ﷺ sagte dies vor der Morgendämmerung während einer Reise."),
        "dua_zawwadakallah" to DuaText("Zum Reisenden: Möge Allah Gottesfurcht gewähren", "Möge Allah dich auf deiner Reise mit Gottesfurcht versorgen, dir deine Sünden vergeben und dir das Gute leicht machen, wo auch immer du bist.", "Beim Verabschieden eines Reisenden.", "Der Prophet ﷺ gab dieses Bittgebet jemandem, der sich auf eine Reise begab."),
        "dua_traveller_to_resident" to DuaText("Der Reisende zu den Zurückbleibenden", "Ich vertraue euch Allah an, bei dem Anvertrautes niemals verloren geht.", "Gesprochen vom Reisenden bei der Verabschiedung der Familie.", "Die Sicherheit der Familie Allah anvertrauen."),
        "dua_entering_village" to DuaText("Eine Stadt oder ein Dorf betreten", "O Allah, Herr der sieben Himmel und all dessen, was sie beschatten, Herr der sieben Erden und all dessen, was sie tragen, Herr der Teufel und all dessen, was sie irreleiten, Herr der Winde und all dessen, was sie zerstreuen! Wir bitten Dich um das Gute dieser Stadt und das Gute ihrer Bewohner, und wir suchen Zuflucht bei Dir vor ihrem Übel, dem Übel ihrer Bewohner und dem Übel dessen, was in ihr ist.", "Vor dem Betreten einer Stadt.", "Der Prophet ﷺ rezitierte dies, wann immer er eine Stadt betreten wollte."),
        "dua_vehicle_stumbles" to DuaText("Wenn das Fahrzeug stolpert", "Im Namen Allahs.", "Wenn das Reittier oder Fahrzeug ausrutscht oder stolpert, anstatt 'Möge Satan zugrunde gehen' zu sagen.", "Bismillah zu sagen lässt Satan auf die Größe einer Fliege schrumpfen."),
        "dua_ajz_kasal_haram" to DuaText("Zuflucht vor Schwäche und Alter", "O Allah, ich suche Zuflucht bei Dir vor Hilflosigkeit und Faulheit, vor Feigheit und Alter, vor den Prüfungen des Lebens und des Todes, und vor der Strafe des Grabes.", "Ein umfassendes tägliches Zufluchtsgebet.", "Ein Bittgebet, das der Prophet ﷺ oft sprach."),
        "dua_sharri_ma_amiltu" to DuaText("Zuflucht vor dem Übel meiner Taten", "O Allah, ich suche Zuflucht bei Dir vor dem Übel dessen, was ich getan habe, und vor dem Übel dessen, was ich nicht getan habe.", "Ein Bittgebet des Propheten ﷺ, nach Aisha (RA).", "Schutz vor den Folgen dessen, was getan und was unterlassen wurde."),
        "dua_jahdil_bala" to DuaText("Zuflucht vor schweren Prüfungen", "O Allah, ich suche Zuflucht bei Dir vor schwerer Prüfung, davor, vom Elend eingeholt zu werden, vor bösem Schicksal und vor der Schadenfreude der Feinde.", "Zuflucht vor schweren Prüfungen und der Schadenfreude der Feinde.", "Der Prophet ﷺ suchte Zuflucht vor diesen vier Dingen."),
        "dua_fitnat_ghina_faqr" to DuaText("Zuflucht vor den Prüfungen des Reichtums und der Armut", "O Allah, ich suche Zuflucht bei Dir vor Faulheit und Alter, vor Sünde und Schuld, vor der Prüfung und Strafe des Grabes, vor der Prüfung und Strafe des Feuers, vor dem Übel der Prüfung des Reichtums, und vor der Prüfung der Armut.", "Zuflucht vor den Prüfungen des Grabes, der Hölle, des Reichtums und der Armut (Teil des Bittgebets).", "Ein umfassendes Zufluchtsgebet des Propheten ﷺ."),
        "dua_sharri_sami" to DuaText("Zuflucht vor dem Übel meiner Sinne", "O Allah, ich suche Zuflucht bei Dir vor dem Übel meines Gehörs, dem Übel meines Sehens, dem Übel meiner Zunge, dem Übel meines Herzens und dem Übel meiner Begierde.", "Shakal ibn Humayd (RA) gelehrt.", "Ein Bittgebet zum Schutz der Glieder und des Selbst vor Sünde."),
        "dua_hadm_gharaq" to DuaText("Zuflucht vor plötzlichem Tod und Unfällen", "O Allah, ich suche Zuflucht bei Dir davor, (von einem Gebäude) zerquetscht zu werden, aus großer Höhe zu fallen, zu ertrinken, zu verbrennen und vor dem Alter; davor, dass Satan mich zur Todesstunde irreführt, davor, auf der Flucht vor Deinem Weg zu sterben, und davor, an einem (giftigen) Stich zu sterben.", "Zuflucht vor Unfällen und einem schlechten Tod.", "Ein Zufluchtsgebet des Propheten ﷺ."),
        "dua_ju_khiyanah" to DuaText("Zuflucht vor Hunger und Verrat", "O Allah, ich suche Zuflucht bei Dir vor Hunger, denn er ist ein übler Begleiter, und ich suche Zuflucht bei Dir vor Verrat, denn er ist ein übler Vertrauter.", "Zuflucht vor Hunger und Verrat.", "Ein Zufluchtsgebet des Propheten ﷺ."),
        "dua_huda_tuqa" to DuaText("Rechtleitung, Frömmigkeit, Keuschheit und Genügsamkeit", "O Allah, ich bitte Dich um Rechtleitung, Frömmigkeit, Keuschheit und Genügsamkeit.", "Ein kurzes, umfassendes Bittgebet des Propheten ﷺ.", "Vier grundlegende Segnungen der Religion und dieser Welt."),
        "dua_aslih_li_dini" to DuaText("Bessere meine Religion, Welt und mein Jenseits", "O Allah, ordne meine Religion, die der Schutz all meiner Angelegenheiten ist; ordne mein weltliches Leben, in dem mein Lebensunterhalt liegt; und ordne mein Jenseits, zu dem ich zurückkehren werde. Mache das Leben für mich zu einer Zunahme in allem Guten, und mache den Tod für mich zu einer Erleichterung von allem Übel.", "Verbesserung der Religion, dieser Welt und des Jenseits — alle drei.", "Ein umfassendes Bittgebet des Propheten ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Wende unsere Herzen zu Deinem Gehorsam", "O Allah, Wender der Herzen, wende unsere Herzen zu Deinem Gehorsam.", "Ein Bittgebet, um das Herz im Gehorsam zu festigen.", "Die Herzen aller Menschen sind zwischen zwei Fingern des Allbarmherzigen."),
        "dua_jannah_nar" to DuaText("Um das Paradies bitten, Zuflucht vor dem Feuer", "O Allah, ich bitte Dich um das Paradies und ich suche Zuflucht bei Dir vor dem Feuer.", "Nach dem Tashahhud oder zu jeder Zeit.", "Der Prophet ﷺ sagte: Auch unsere Bittgebete drehen sich darum."),
        "dua_khayri_kullih" to DuaText("Alles Gute, jetzt und später", "O Allah, ich bitte Dich um alles Gute — das Unmittelbare und das Aufgeschobene, was ich weiß und was ich nicht weiß — und ich suche Zuflucht bei Dir vor allem Übel — dem Unmittelbaren und dem Aufgeschobenen, was ich weiß und was ich nicht weiß. O Allah, ich bitte Dich um das Paradies und um alles, was mich in Worten und Taten näher dazu bringt, und ich suche Zuflucht bei Dir vor dem Feuer und vor allem, was mich in Worten und Taten näher dazu bringt.", "Der Prophet ﷺ lehrte dieses umfassende Bittgebet Aisha (RA) (Teil des Bittgebets).", "Ein Bittgebet, das jedes Gut vereint."),
        "dua_ihdini_saddidni" to DuaText("Leite mich und halte mich aufrecht", "O Allah, leite mich und halte mich auf dem rechten Kurs.", "Der Prophet ﷺ lehrte es Ali (RA).", "Denke an Rechtleitung als das Führen auf einer Straße, und an Sadad als die Geradheit eines Pfeils."),
        "dua_hubbaka" to DuaText("Um Allahs Liebe bitten", "O Allah, ich bitte Dich um Deine Liebe, die Liebe derer, die Dich lieben, und Taten, die mich Deiner Liebe näherbringen. O Allah, mache Deine Liebe mir lieber als mich selbst, meine Familie und kühles Wasser.", "Das Bittgebet des Dawud (Friede sei mit ihm), überliefert vom Propheten ﷺ.", "Die Liebe Allahs ist der größte Reichtum."),
        "dua_filal_khayrat" to DuaText("Gutes tun und Böses lassen", "O Allah, ich bitte Dich, mir zu ermöglichen, gute Taten zu tun, böse Taten zu lassen und die Armen zu lieben, und dass Du mir vergibst und Dich meiner erbarmst. Und wenn Du eine Prüfung für ein Volk beabsichtigst, nimm mich, ohne geprüft zu werden. Ich bitte Dich um Deine Liebe, die Liebe derer, die Dich lieben, und die Liebe zu Taten, die mich Deiner Liebe näherbringen.", "Allah lehrte dieses Bittgebet dem Propheten ﷺ in einem Traum.", "Der Prophet ﷺ sagte: Es ist wahr, also lerne es und lehre es."),
        "dua_bi_ilmikal_ghayb" to DuaText("Lass mich leben, solange das Leben gut ist", "O Allah, durch Dein Wissen über das Verborgene und Deine Macht über die Schöpfung — halte mich am Leben, solange Du weißt, dass das Leben besser für mich ist, und nimm mich, wenn Du weißt, dass der Tod besser für mich ist. O Allah, ich bitte Dich um Furcht vor Dir im Verborgenen und in der Öffentlichkeit, um das Wort der Wahrheit in Zufriedenheit und im Zorn, und um Mäßigung in Armut und Reichtum.", "Das Gebets-Bittgebet des Ammar ibn Yasir (RA) (Eröffnungsteil).", "Der Prophet ﷺ sprach dieses Bittgebet im Gebet."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "O Allah, ich bitte Dich, denn Dir gebührt alles Lob; es gibt keinen Gott außer Dir, den Gewährer von Gunsterweisen, den Urheber der Himmel und der Erde. O Besitzer von Majestät und Ehre, o Ewig-Lebender, o Erhalter!", "Der Prophet ﷺ sagte, dieser Mann habe mit Allahs größtem Namen gebetet.", "Ein Bittgebet mit diesem Namen wird erhört."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "O Allah, ich bitte Dich, denn ich bezeuge, dass Du Allah bist; es gibt keinen Gott außer Dir, der Eine, der Selbstgenügsame, der weder zeugt noch gezeugt wurde, und dem niemand gleicht.", "Der Prophet ﷺ sagte, dieser Mann habe Allah bei Seinem größten Namen gebeten.", "Wenn man bei ihm bittet, gibt Er; wenn man bei ihm ruft, antwortet Er."),
        "dua_thabbitni_hadiyan" to DuaText("Mach mich fest, geleitet und ein Führer", "O Allah, mach mich fest, und mach mich zu einem, der leitet und geleitet wird.", "Der Prophet ﷺ sprach dieses Bittgebet für Jarir (RA) (für sich selbst sage 'thabbitni').", "Das ursprüngliche Bittgebet für Jarir (RA) verwendet die Worte 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("Vergib mir und nimm meine Reue an", "Mein Herr, vergib mir und nimm meine Reue an. Wahrlich, Du bist der Annehmer der Reue, der Barmherzige.", "Hundertmal in einer einzigen Sitzung — die Praxis des Propheten ﷺ.", "Die Gefährten zählten, dass der Prophet ﷺ es hundertmal in einer Sitzung sagte."),
        "dua_rafiq_ala" to DuaText("Bittgebet des Sterbenden", "O Allah, vergib mir, erbarme Dich meiner und vereine mich mit dem Höchsten Gefährten.", "Das letzte Bittgebet des Propheten ﷺ — für den Kranken, es für sich selbst zu sagen.", "Der Prophet ﷺ sprach dieses Bittgebet zur Zeit seines Hinscheidens."),
        "dua_la_bas_tahur" to DuaText("Den Kranken trösten: Reinigung", "Kein Schaden; es ist eine Reinigung (von Sünden), so Allah will.", "Um den Kranken beim Besuch zu trösten.", "Der Prophet ﷺ sagte dies beim Besuch der Kranken."),
        "dua_talqeen" to DuaText("Talqin für den Sterbenden", "Es gibt keinen Gott außer Allah.", "Rezitiere die Kalimah in der Nähe eines Sterbenden (zwinge ihn nicht, sie zu sagen).", "Wessen letzte Worte 'La ilaha illallah' sind, wird ins Paradies eintreten (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Anstatt sich den Tod zu wünschen", "O Allah, lass mich leben, solange das Leben besser für mich ist, und nimm mich, wenn der Tod besser für mich ist.", "Anstatt sich in Not den Tod zu wünschen.", "Der Prophet ﷺ verbot, sich den Tod zu wünschen, und lehrte dies stattdessen."),
        "dua_for_one_i_cursed" to DuaText("Für jemanden, den ich mit Worten verletzt habe", "O Allah, jeden Gläubigen, den ich beleidigt habe, mache dies für ihn am Tag der Auferstehung zu einem Mittel der Nähe zu Dir.", "Für jemanden, mit dem man im Zorn schlecht gesprochen hat.", "Ein Bittgebet des Propheten ﷺ."),
        "dua_praising_someone" to DuaText("Beim Loben von jemandem", "Ich halte den Soundso für so, und Allah ist sein Rechenschaftsprüfer, und ich bürge vor Allah für niemandes Reinheit.", "Beim Loben von jemandem, anstatt zu übertreiben.", "Der Prophet ﷺ lehrte diese Etikette des Lobs."),
        "dua_being_praised" to DuaText("Wenn du gelobt wirst", "O Allah, ziehe mich nicht zur Rechenschaft für das, was sie sagen, und vergib mir für das, was sie nicht wissen.", "Beim Hören des eigenen Lobs — die Praxis eines Gefährten (RA).", "Ein Weg, um Hochmut beim Loben zu vermeiden."),
        "dua_non_muslim_sneezes" to DuaText("Wenn ein Nicht-Muslim niest", "Möge Allah dich rechtleiten und deine Angelegenheiten in Ordnung bringen.", "Wenn ein Nicht-Muslim niest und 'Alhamdulillah' sagt.", "Juden niesten in der Nähe des Propheten ﷺ in der Hoffnung, dass er 'Yarhamukallah' sagen würde, und er sagte dies."),
        "dua_reply_ahl_kitab_salam" to DuaText("Auf den Salam der Schriftbesitzer antworten", "Und auch mit euch.", "Wenn die Schriftbesitzer mit Salam grüßen.", "Die Anweisung des Propheten ﷺ."),
        "dua_fasting_invited" to DuaText("Wenn man fastend eingeladen wird", "Ich faste.", "Wenn man fastend eingeladen wird, oder wenn jemand mit einem streitet.", "Wenn der Fastende eine Einladung annimmt, sollte er für den Gastgeber beten."),
        "dua_for_who_gave_drink" to DuaText("Für wer mich gespeist hat", "O Allah, speise den, der mich gespeist hat, und gib dem zu trinken, der mir zu trinken gegeben hat.", "Für jeden, der dir Essen oder Trinken gibt.", "Der Prophet ﷺ sprach dieses Bittgebet für al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Eid-Gruß", "Möge Allah (gute Taten) von uns und von euch annehmen.", "Untereinander am Tag des Eid — die Praxis der edlen Gefährten (RA).", "Die Gefährten sagten dies, wenn sie sich am Eid trafen."),
        "dua_wedding_night" to DuaText("Für die Braut nach dem Nikah", "O Allah, ich bitte Dich um ihr Gutes und das Gute der Natur, mit der Du sie erschaffen hast, und ich suche Zuflucht bei Dir vor ihrem Übel und dem Übel der Natur, mit der Du sie erschaffen hast.", "Nach dem Nikah, die Hand auf die Stirn der Ehefrau legend.", "Die Lehre des Propheten ﷺ — Segen in der Ehe."),
        "dua_istisqa_ibadak" to DuaText("Tränke Deine Diener und Tiere", "O Allah, gib Deinen Dienern und Deinen Tieren Wasser, verbreite Deine Barmherzigkeit und belebe Dein totes Land.", "Um Regen bitten (Istisqa).", "Der Prophet ﷺ sprach dieses Bittgebet um Regen."),
        "dua_seeing_clouds" to DuaText("Dunkle Wolken sehen", "O Allah, ich suche Zuflucht bei Dir vor ihrem Übel.", "Beim Sehen dunkler Wolken am Himmel; wenn es regnet, sage 'Allahumma sayyiban nafi'a'.", "Beim Sehen von Wolken ließ der Prophet ﷺ ab, was er tat, und sprach dieses Bittgebet."),
        "dua_jamarat" to DuaText("Die Jamarat steinigen", "Allah ist der Größte.", "Bei jedem geworfenen Steinchen.", "Der Prophet ﷺ sprach den Takbir bei jedem Steinchen und wandte sich nach der ersten und zweiten Jamrah zur Qibla und sprach ein langes Bittgebet."),
        "dua_rabbi_ainni" to DuaText("Mein Herr, hilf mir und nicht gegen mich", "Mein Herr, hilf mir und hilf nicht anderen gegen mich, gewähre mir den Sieg und gewähre anderen nicht den Sieg über mich, plane für mich und plane nicht gegen mich, leite mich und mache mir die Rechtleitung leicht, und hilf mir gegen den, der mir Unrecht tut.", "Ein umfassendes Bittgebet des Propheten ﷺ (Eröffnungsteil).", "Ein Bittgebet, das jede Hilfe in Religion und dieser Welt vereint."),
        "dua_ati_nafsi_taqwaha" to DuaText("Gewähre meiner Seele ihre Gottesfurcht", "O Allah, gewähre meiner Seele ihre Frömmigkeit und reinige sie, denn Du bist der Beste, um sie zu reinigen. Du bist ihr Wächter und ihr Herr.", "Zur Besserung und Reinigung des Selbst.", "Der Prophet ﷺ pflegte dieses Bittgebet zu sprechen."),
        "dua_iqsim_lana_khashyatik" to DuaText("Gewähre uns solche Furcht vor Dir", "O Allah, gewähre uns genug Furcht vor Dir, um zwischen uns und dem Ungehorsam gegen Dich zu stehen, genug Gehorsam, um uns zu Deinem Paradies zu bringen, und genug Gewissheit, um uns die Prüfungen dieser Welt leicht zu machen. Lass uns unser Gehör, unser Sehen und unsere Kraft genießen, solange Du uns am Leben lässt, und mache sie länger anhaltend als uns. Räche uns an denen, die uns Unrecht tun, hilf uns gegen unsere Feinde, lass unser Unglück nicht unsere Religion betreffen, mache diese Welt nicht zu unserem größten Anliegen oder der Grenze unseres Wissens, und setze niemanden über uns, der uns keine Gnade erweist.", "Beim Aufstehen aus einer Versammlung — der Prophet ﷺ erhob sich selten, ohne dieses Bittgebet zu sprechen.", "Ein umfassendes Bittgebet für das Wohl von Religion, dieser Welt und dem Jenseits."),
        "dua_infani_bima_allamtani" to DuaText("Nütze mir mit dem, was Du mich gelehrt hast", "O Allah, nütze mir mit dem, was Du mich gelehrt hast, lehre mich, was mir nützt, und mehre mein Wissen.", "Beim Wissenserwerb oder vor dem Lernen.", "Ein Bittgebet um nützliches Wissen und danach zu handeln."),
        "dua_jar_su" to DuaText("Zuflucht vor einem schlechten Nachbarn", "O Allah, ich suche Zuflucht bei Dir vor einem schlechten Nachbarn am Ort des dauerhaften Wohnsitzes, denn der Nachbar auf Reisen zieht weiter.", "Für Schutz vor einem schlechten Nachbarn.", "Der Prophet ﷺ befahl, davor Zuflucht zu suchen."),
        "dua_ishfi_abdak" to DuaText("Für die Genesung eines Kranken", "O Allah, heile Deinen Diener, damit er für Dich einem Feind entgegentreten oder für Dich zum Gebet gehen kann.", "Für den Kranken beim Besuch.", "Der Prophet ﷺ lehrte, dies für den Kranken zu sagen."),
        "dua_la_mania" to DuaText("Niemand kann zurückhalten, was Du gibst", "Es gibt keinen Gott außer Allah, allein, ohne Partner. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge. O Allah, niemand kann zurückhalten, was Du gibst, und niemand kann geben, was Du zurückhältst, und der Reichtum der Reichen nützt nichts gegen Dich.", "Nach dem Salam des Pflichtgebets.", "Der Prophet ﷺ sagte dies nach jedem Pflichtgebet."),
        "dua_slaughtering" to DuaText("Beim Schlachten eines Tieres", "Im Namen Allahs, und Allah ist der Größte.", "Beim Opfern oder Schlachten eines Tieres.", "Der Prophet ﷺ sprach Bismillah und Takbir zur Zeit des Opferns."),
        "dua_undressing" to DuaText("Beim Ausziehen der Kleidung", "Im Namen Allahs.", "Beim Ausziehen der Kleidung (für Ghusl oder Umziehen).", "Es wird zu einem Schutzschild zwischen den Augen der Dschinn und den privaten Bereichen einer Person."),
        "dua_ilbas_jadidan" to DuaText("Jemanden in neuer Kleidung sehen", "Trage es neu, lebe lobenswert und stirb als Märtyrer.", "Beim Sehen eines muslimischen Bruders in neuer Kleidung.", "Der Prophet ﷺ sprach dieses Bittgebet beim Anblick Umars (RA) in neuer Kleidung."),
        "dua_hajj_la_riya" to DuaText("Ein Hajj frei von Zurschaustellung", "O Allah, (mache ihn zu) einem Hajj ohne Zurschaustellung und ohne Ruhmsucht.", "Für Aufrichtigkeit bei der Absicht zum Hajj.", "Der Prophet ﷺ sprach dieses Bittgebet zur Zeit des Hajj."),
        "dua_q_muslimayni_laka" to DuaText("Bittgebet von Ibrahim und Ismail (Friede sei mit ihnen) — Mache uns Dir ergeben", "Unser Herr, mache uns beide Dir ergeben und aus unseren Nachkommen eine Dir ergebene Gemeinschaft. Zeige uns unsere Riten der Anbetung und nimm unsere Reue an. Wahrlich, Du bist der Annehmer der Reue, der Barmherzige.", "Ein Bittgebet der Ergebenheit für sich selbst und die Nachkommen.", "Das Bittgebet, gesprochen beim Bau der Kaaba."),
        "dua_q_iftah_baynana" to DuaText("Bittgebet des Shu'aib (Friede sei mit ihm) — Richte zwischen uns", "Unser Herr, richte zwischen uns und unserem Volk in Wahrheit, und Du bist der Beste der Richter.", "Für ein Urteil zwischen Wahrheit und Falschheit.", "Das Bittgebet des Shu'ayb (Friede sei mit ihm), als sein Volk ihn ablehnte."),
        "dua_q_la_akuna_zahiran" to DuaText("Bittgebet des Musa (Friede sei mit ihm) — Niemals ein Helfer der Verbrecher", "Mein Herr, wegen der Gunst, die Du mir erwiesen hast, werde ich niemals ein Helfer der Verbrecher sein.", "Dankbarkeit für Allahs Gnaden und ein Versprechen, Unrechtstätern nicht zu helfen.", "Das Gelöbnis des Musa (Friede sei mit ihm) nach seiner Reue."),
        "dua_q_nuh_unsurni" to DuaText("Bittgebet des Nuh (Friede sei mit ihm) — Hilf mir, sie leugnen mich", "Mein Herr, hilf mir, denn sie haben mich geleugnet.", "Wenn Menschen dich leugnen und die Wahrheit ablehnen.", "Das Bittgebet des Nuh (Friede sei mit ihm), das erhört wurde."),
        "dua_q_ihkum_bil_haqq" to DuaText("Mein Herr, richte mit Wahrheit", "Mein Herr, richte mit Wahrheit. Und unser Herr ist der Allbarmherzige, dessen Hilfe gegen das gesucht wird, was ihr beschreibt.", "Angesichts von Lügen und falschen Anschuldigungen.", "Ein Bittgebet, das dem Propheten ﷺ gelehrt wurde."),
        "dua_ghalabatid_dayn" to DuaText("Zuflucht vor erdrückenden Schulden und Feinden", "O Allah, ich suche Zuflucht bei Dir davor, von Schulden überwältigt zu werden, von einem Feind überwältigt zu werden und vor der Schadenfreude der Feinde.", "Schutz vor der Last der Schulden und der Beherrschung durch Feinde.", "Der Prophet ﷺ suchte Zuflucht vor diesen Dingen."),
        "dua_faqr_qillah_dhillah" to DuaText("Zuflucht vor Armut und Demütigung", "O Allah, ich suche Zuflucht bei Dir vor Armut, Knappheit und Demütigung, und davor, anderen Unrecht zu tun oder Unrecht erlitten zu werden.", "Um sicher zu sein vor Not, Mangel und Demütigung.", "Eine vom Propheten ﷺ gelehrte Zuflucht."),
        "dua_five_things_new_muslim" to DuaText("Vergib, erbarme Dich, leite, heile, versorge", "O Allah, vergib mir, erbarme Dich meiner, leite mich, gewähre mir Wohlergehen und versorge mich.", "Der Prophet ﷺ lehrte dieses Bittgebet, zusammen mit dem Gebet, neuen Muslimen.", "Der Prophet ﷺ sagte: Diese Worte vereinen für dich diese Welt und das Jenseits."),
        "dua_ruku_laka_raka_tu" to DuaText("Im Ruku — Dir habe ich mich verneigt", "O Allah, vor Dir habe ich mich verneigt, an Dich habe ich geglaubt und Dir habe ich mich unterworfen. Mein Gehör, mein Sehen, mein Verstand, meine Knochen und meine Sehnen sind demütig vor Dir.", "Im Ruku (besonders in freiwilligen Gebeten).", "Der Prophet ﷺ rezitierte dies im Ruku."),
        "dua_sujood_laka_sajadtu" to DuaText("Im Sujud — Dir habe ich mich niedergeworfen", "O Allah, vor Dir habe ich mich niedergeworfen, an Dich habe ich geglaubt und Dir habe ich mich unterworfen. Mein Gesicht hat sich vor Dem niedergeworfen, Der es erschaffen, geformt und sein Hören und Sehen hervorgebracht hat. Gesegnet sei Allah, der beste der Schöpfer.", "Im Sujud (besonders in freiwilligen Gebeten).", "Der Prophet ﷺ rezitierte dies im Sujud."),
        "dua_ruku_sujood_subhanaka" to DuaText("Gepriesen seist Du, unser Herr — Vergib mir", "Gepriesen seist Du, o Allah, unser Herr, und Lob sei Dir. O Allah, vergib mir.", "Im Ruku und Sujud.", "Aisha (RA): Der Prophet ﷺ sagte dies oft im Ruku und Sujud."),
        "dua_q_musa_li_akhi" to DuaText("Bittgebet des Musa (Friede sei mit ihm) — Vergib mir und meinem Bruder", "Mein Herr, vergib mir und meinem Bruder und nimm uns auf in Deine Barmherzigkeit, denn Du bist der Barmherzigste der Barmherzigen.", "Vergebung für sich selbst und den eigenen Bruder oder Liebsten.", "Das Bittgebet des Musa (Friede sei mit ihm) für Harun (Friede sei mit ihm)."),
        "dua_q_ufawwidu_amri" to DuaText("Ich vertraue meine Angelegenheit Allah an", "Und ich vertraue meine Angelegenheit Allah an. Wahrlich, Allah sieht Seine Diener wohl.", "Wenn Menschen sich dir widersetzen und die Angelegenheit Allah überlassen werden muss.", "Die Worte des Gläubigen aus dem Volk Pharaos; Allah beschützte ihn danach vor ihren bösen Plänen."),
        "dua_q_hawariyyun" to DuaText("Bittgebet der Jünger — Verzeichne uns mit den Zeugen", "Unser Herr, wir haben an das geglaubt, was Du offenbart hast, und wir sind dem Gesandten gefolgt, also verzeichne uns unter den Zeugen.", "Für Standhaftigkeit im Glauben und im Befolgen des Gesandten.", "Das Bittgebet der Jünger von Isa (Friede sei mit ihm)."),
        "dua_q_la_tukhzini" to DuaText("Bittgebet des Ibrahim (Friede sei mit ihm) — Beschäme mich nicht", "Und beschäme mich nicht an dem Tag, an dem sie auferweckt werden.", "Um vor Schande am Tag der Auferstehung sicher zu sein.", "Das Bittgebet des Ibrahim (Friede sei mit ihm) für das Jenseits."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar — Für Dich habe ich gefastet", "O Allah, für Dich habe ich gefastet und mit Deiner Versorgung breche ich mein Fasten.", "Beim Fastenbrechen (das bekannte Iftar-Bittgebet).", "Der Prophet ﷺ sagte dies beim Iftar. Es ist eine mursal-Überlieferung, gestärkt durch andere Überlieferungen; es beim Iftar zu rezitieren ist die Praxis der Hanafiten und der Mehrheit."),
        "dua_iftar_ibn_umar" to DuaText("Iftar — Durch Deine weite Barmherzigkeit, vergib mir", "O Allah, ich bitte Dich bei Deiner Barmherzigkeit, die alle Dinge umfasst, mir zu vergeben.", "Beim Iftar — Abdullah ibn Amr (RA) sprach dieses Bittgebet; das Bittgebet eines Fastenden beim Iftar wird nicht zurückgewiesen.", "Hadith: Das Bittgebet des Fastenden zur Zeit des Iftar wird nicht zurückgewiesen."),
        "dua_inni_saim" to DuaText("Wenn man fastend provoziert wird", "Ich faste, ich faste.", "Wenn dich jemand beleidigt oder mit dir streitet, während du fastest.", "Der Prophet ﷺ sagte: Das Fasten ist ein Schild, also sollte der Fastende nicht obszön sprechen oder unwissend handeln — wenn jemand streitet, sage dies zweimal."),
        "dua_eid_takbeer" to DuaText("Takbir auf dem Weg zum Eid", "Allah ist der Größte, Allah ist der Größte, es gibt keinen Gott außer Allah, und Allah ist der Größte, Allah ist der Größte, und alles Lob gebührt Allah.", "Von der Nacht der Mondsichtung bis zum Eid-al-Fitr-Gebet, besonders auf dem Weg zum Eid-Platz.", "Der koranische Befehl: 'damit ihr die Zahl vollendet und Allahs Größe verkündet' (al-Baqarah 2:185). Ibn Mas'ud (RA) sprach diesen Takbir."),
        "dua_ahsin_aqibatana" to DuaText("Mache unser Ende gut in allen Angelegenheiten", "O Allah, mache unser Ende gut in allen Angelegenheiten, und bewahre uns vor Schande in dieser Welt und Strafe im Jenseits.", "Für ein gutes Ergebnis in jeder Angelegenheit.", "Wer dieses Bittgebet spricht und stirbt, bevor er geprüft wird, stirbt (sicher vor der Prüfung)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Ich bitte um Deine Großzügigkeit und Barmherzigkeit", "O Allah, ich bitte Dich um Deine Großzügigkeit und Deine Barmherzigkeit, denn niemand besitzt sie außer Dir.", "Beim Bitten um Versorgung und Barmherzigkeit.", "Gäste kamen zum Propheten ﷺ, als es kein Essen gab; er sprach dieses Bittgebet, und dann kam eine Gabe an."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Worte, die einem Beduinen gelehrt wurden", "Es gibt keinen Gott außer Allah, allein, ohne Partner. Allah ist der Größte, sehr groß; reichliches Lob gebührt Allah; gepriesen sei Allah, Herr der Welten; und es gibt keine Kraft und keine Macht außer durch Allah, den Allmächtigen, den Allweisen.", "Eine umfassende Formel des Dhikr und Bittgebets — einem Beduinen gelehrt.", "Danach wurde ihm gelehrt zu sagen 'Allahummaghfir li warhamni wahdini warzuqni'."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Vergib, was ich früher und später getan habe", "O Allah, vergib mir die Sünden, die ich früher und später begangen habe, was ich heimlich und was ich offen getan habe, meine Maßlosigkeiten, und was Du besser weißt als ich. Du bist Der, der vorbringt und Der, der zurückstellt; es gibt keinen Gott außer Dir.", "Nach dem Tashahhud und den Segenswünschen, vor dem Salam.", "Der Prophet ﷺ rezitierte dies am Ende des Gebets, zwischen dem Tashahhud und dem Salam."),
        "dua_jiddi_wa_hazli" to DuaText("Vergib meinen Ernst und meinen Scherz", "O Allah, vergib mir die Sünden, die ich ernsthaft und im Scherz begangen habe, aus Versehen und absichtlich — und all das ist in mir.", "Vergebung für jede Art von Sünde, bekannt und unbekannt.", "Eine umfassende Istighfar des Propheten ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Nach dem Ruku — Lob, das die Himmel füllt", "Unser Herr, Dir gebührt alles Lob, füllend die Himmel, füllend die Erde, und füllend, was auch immer Du danach willst.", "Nach dem Aufrichten aus dem Ruku, zusammen mit 'Rabbana lakal-hamd'.", "Der Prophet ﷺ sagte dies beim Aufrichten aus dem Ruku."),
        "dua_istiftah_kabira" to DuaText("Allah ist der Größte, reichlich gepriesen", "Allah ist der Größte, sehr groß; reichliches Lob gebührt Allah; und gepriesen sei Allah morgens und abends.", "Zu Beginn des Gebets (eine Form des Eröffnungslobs).", "Der Prophet ﷺ sagte: Die Tore des Himmels wurden dafür geöffnet."),
        "dua_q_ashku_bathhi" to DuaText("Bittgebet des Yaqub (Friede sei mit ihm) — Ich klage nur Allah", "Ich klage über meinen Kummer und meine Trauer nur Allah.", "In tiefem Kummer und Trennung.", "Ya'qub (Friede sei mit ihm) sagte dies in seiner Trennung von Yusuf (Friede sei mit ihm)."),
        "dua_q_khayrun_hafiza" to DuaText("Allah ist der beste Beschützer", "Allah ist der beste Beschützer, und Er ist der Barmherzigste der Barmherzigen.", "Beim Senden von Kindern oder Liebsten auf eine Reise.", "Ya'qub (Friede sei mit ihm) sagte dies, als er seinen Sohn Allah anvertraute."),
        "dua_q_aqraba_rashada" to DuaText("Möge mein Herr mich näher zur Rechtschaffenheit leiten", "Vielleicht wird mein Herr mich zu etwas leiten, das näher an rechtem Verhalten ist als dies.", "Beim Suchen nach einem besseren Weg in einer Angelegenheit.", "Dem Propheten ﷺ wurde gesagt, dies beim Vergessen zu sagen."),
        "dua_q_sawa_as_sabil" to DuaText("Bittgebet des Musa (Friede sei mit ihm) — Leite mich zum rechten Weg", "Vielleicht wird mein Herr mich zum rechten Weg leiten.", "Beim Aufbruch zu einer neuen Reise oder einem unbekannten Weg.", "Musa (Friede sei mit ihm) sagte dies, als er sich nach Madyan wandte."),
        "dua_q_not_among_wrongdoers" to DuaText("Nicht unter den Ungerechten", "Mein Herr, stelle mich nicht unter das ungerechte Volk.", "Ein Bittgebet, Allah zu bitten, einen von den Ungerechten fernzuhalten.", "Eine kurze, umfassende Zuflucht vor Unrecht."),
        "dua_q_do_not_make_us_trial" to DuaText("Mache uns nicht zu einer Prüfung", "Unser Herr, mache uns nicht zu einer Prüfung für die Ungläubigen, und vergib uns, unser Herr. Wahrlich, Du bist der Allmächtige, der Allweise.", "Das Bittgebet des Ibrahim (Friede sei mit ihm) und seiner Gefährten.", "Ein Bittgebet um Schutz vor Prüfung und um Vergebung."),
        "dua_muawwidhat" to DuaText("Die Schutzsuren (Muawwidhat)", "(Surah al-Ikhlas) Sprich: Er ist Allah, der Einzige. Allah, der Selbstgenügsame. Er zeugt nicht und wurde nicht gezeugt. Und niemand ist Ihm gleich.\n\n(Surah al-Falaq) Sprich: Ich suche Zuflucht beim Herrn der Morgendämmerung, vor dem Übel dessen, was Er erschaffen hat, vor dem Übel der Dunkelheit, wenn sie sich ausbreitet, vor dem Übel derer, die in Knoten blasen, und vor dem Übel des Neiders, wenn er neidet.\n\n(Surah an-Nas) Sprich: Ich suche Zuflucht beim Herrn der Menschen, dem König der Menschen, dem Gott der Menschen, vor dem Übel des zurückweichenden Einflüsterers, der in die Herzen der Menschen einflüstert, von den Dschinn und den Menschen.", "Die drei Suren dreimal jeden Morgen und Abend und vor dem Schlafen, in die Hände blasen und über den Körper wischen.", "Schutz durch die drei Schutzsuren des Korans, gemäß der Sunna des Propheten ﷺ."),
        "dua_morning_witness" to DuaText("Morgendliches Zeugnis", "O Allah, ich bin in den Morgen eingetreten, indem ich Dich, die Träger Deines Throns, Deine Engel und Deine ganze Schöpfung zum Zeugen anrufe, dass Du Allah bist, es gibt keinen Gott außer Dir, allein, ohne Partner, und dass Muhammad ﷺ Dein Diener und Gesandter ist.", "Die Überlieferung erwähnt, es viermal am Morgen zu sagen.", "Ein Bittgebet des Zeugnisses für den Glauben am Morgen."),
        "dua_evening_witness" to DuaText("Abendliches Zeugnis", "O Allah, ich bin in den Abend eingetreten, indem ich Dich, die Träger Deines Throns, Deine Engel und Deine ganze Schöpfung zum Zeugen anrufe, dass Du Allah bist, es gibt keinen Gott außer Dir, allein, ohne Partner, und dass Muhammad ﷺ Dein Diener und Gesandter ist.", "Die Überlieferung erwähnt, es viermal am Abend zu sagen.", "Ein Bittgebet des Zeugnisses für den Glauben am Abend."),
        "dua_morning_blessing" to DuaText("Morgendlicher Segen", "O Allah, welche Gnade auch immer ich oder irgendeine Deiner Schöpfungen heute Morgen erhalten haben, sie ist von Dir allein, ohne Partner; Dir gebührt also alles Lob und aller Dank.", "Morgendliches Dhikr der Dankbarkeit für Allahs Gnaden.", "Ein Gebet der Anerkennung, dass alle Gnaden von Allah allein kommen."),
        "dua_evening_blessing" to DuaText("Abendlicher Segen", "O Allah, welche Gnade auch immer ich oder irgendeine Deiner Schöpfungen heute Abend erhalten haben, sie ist von Dir allein, ohne Partner; Dir gebührt also alles Lob und aller Dank.", "Abendliches Dhikr der Dankbarkeit für Allahs Gnaden.", "Ein Gebet der Anerkennung, dass alle Gnaden von Allah allein kommen."),
    )
}
